local function TryLoadAccent()
    if not (readfile and isfile) then return end
    local ok, raw = pcall(function()
        if not isfile("_CatalystConfigs/_meta.json") then return nil end
        return readfile("_CatalystConfigs/_meta.json")
    end)
    if not ok or not raw then return end
    local dok, meta = pcall(function() return HttpService:JSONDecode(raw) end)
    if not dok or type(meta) ~= "table" or not meta.recent then return end
    local cfgPath = "_CatalystConfigs/" .. meta.recent .. ".json"
    local cok, craw = pcall(function()
        if not isfile(cfgPath) then return nil end
        return readfile(cfgPath)
    end)
    if not cok or not craw then return end
    local fok, flags = pcall(function() return HttpService:JSONDecode(craw) end)
    if not fok or type(flags) ~= "table" then return end
    local customOn = flags["_customaccent"]
    local a = flags["_accent"]
    if customOn == true and type(a) == "table" and a.__c3 then
        Theme.Accent = Color3.new(a.__c3[1], a.__c3[2], a.__c3[3])
        return
    end
    local themeName = flags["_theme"]
    local themeAccents = {
        GX      = Color3.fromRGB(220, 38,  38),
        Discord = Color3.fromRGB(88,  101, 242),
        Light   = Color3.fromRGB(59,  130, 246),
    }
    if themeName and themeAccents[themeName] then
        Theme.Accent = themeAccents[themeName]
    end
end
pcall(TryLoadAccent)

local function Tween(obj, props, t, style, dir)
    if not obj or not obj.Parent then return end
    local tw = TweenService:Create(
        obj,
        TweenInfo.new(t or 0.2, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out),
        props
    )
    tw:Play()
    return tw
end

local function Corner(obj, r)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, r or 6)
    c.Parent = obj
    return c
end

local function MkStroke(obj, col, th)
    local s = Instance.new("UIStroke")
    s.Color = col or Theme.Stroke
    s.Thickness = th or 1
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.Parent = obj
    return s
end

local function MakeFolder(p)
    if makefolder and isfolder and not isfolder(p) then
        pcall(makefolder, p)
    end
end

local function SaveKey(key)
    if not writefile then return end
    MakeFolder("Catalyst")
    MakeFolder("Catalyst/KeySystem")
    pcall(writefile, "Catalyst/KeySystem/saved_key.txt", key)
end

local function GetSavedKey()
    if not (readfile and isfile) then return nil end
    local ok, k = pcall(function()
        if isfile("Catalyst/KeySystem/saved_key.txt") then
            return readfile("Catalyst/KeySystem/saved_key.txt")
        end
    end)
    return (ok and k and k ~= "") and k or nil
end

local function HookTamper()
    local chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    local function rnd()
        local t = {}
        for _ = 1, math.random(6, 18) do
            t[#t+1] = chars:sub(math.random(1, #chars), math.random(1, #chars))
        end
        return table.concat(t)
    end
    local mod = Instance.new("ModuleScript")
    mod.Name = "Catalyst"
    mod.Parent = game
    local vals = {}
    for _ = 1, 13 do
        local v = Instance.new("StringValue")
        v.Name = "__"..rnd()
        v.Value = rnd()
        v.Parent = mod
        vals[#vals+1] = v
    end
    task.spawn(function()
        while task.wait() do
            for _, v in ipairs(vals) do
                v.Name = "__"..rnd()
                v.Value = rnd()
            end
        end
    end)
end

