end)

local function SetStatus(msg, state)
    StatusLbl.Text = msg
    if state == "error" then
        StatusLbl.TextColor3 = Color3.fromRGB(255, 85, 100)
        StatusDot.BackgroundColor3 = Color3.fromRGB(255, 85, 100)
    elseif state == "success" then
        StatusLbl.TextColor3 = Color3.fromRGB(100, 220, 130)
        StatusDot.BackgroundColor3 = Color3.fromRGB(100, 220, 130)
    elseif state == "active" then
        StatusLbl.TextColor3 = Theme.Accent
        StatusDot.BackgroundColor3 = Theme.Accent
    else
        StatusLbl.TextColor3 = Theme.SubText
        StatusDot.BackgroundColor3 = Theme.SubText
    end
end

local function ShowProgress()
    ProgBG.BackgroundTransparency = 0
    Tween(ProgFill, { Size = UDim2.new(0.65, 0, 1, 0) }, 1.4, Enum.EasingStyle.Quart)
end

local function FinishProgress(success)
    Tween(ProgFill, {
        Size = UDim2.new(success and 1 or 0, 0, 1, 0),
        BackgroundColor3 = success and Color3.fromRGB(100, 220, 130) or Color3.fromRGB(255, 85, 100)
    }, 0.28)
    task.delay(0.55, function()
        Tween(ProgBG, { BackgroundTransparency = 1 }, 0.28)
        ProgFill.BackgroundColor3 = Theme.Accent
        ProgFill.Size = UDim2.new(0, 0, 1, 0)
    end)
end

local function DismissUI()
    Tween(WinScale, { Scale = 0.94 }, 0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
    Tween(Win, { BackgroundTransparency = 1 }, 0.32)
    Tween(Blur, { Size = 0 }, 0.32)
    task.delay(0.38, function()
        pcall(function() Screen:Destroy() end)
        pcall(function() Blur:Destroy() end)
    end)
end

local SCRIPTS = {
    [7518216173] = "",
}

local function LoadScript()
    local url = SCRIPTS[game.GameId]
    if not url then
        SetStatus("Game not supported", "error")
        return false
    end
    local ok, src = pcall(function() return game:HttpGet(url) end)
    if not ok or not src then
        SetStatus("Download failed", "error")
        return false
    end
    local lok, chunk = pcall(loadstring, src)
    if not lok or not chunk then
        SetStatus("Load error", "error")
        return false
    end
    FinishProgress(true)
    SetStatus("Launching...", "success")
    task.wait(0.45)
    DismissUI()
    task.spawn(function() pcall(chunk) end)
    return true
end

local verifying = false
local function VerifyKey(key)
    if verifying then return end
    key = key:gsub("%s+", "")
    if key == "" then SetStatus("Please enter a key", "error"); return end
    verifying = true

    SetStatus("Verifying...", "active")
    ShowProgress()
    Tween(VerifyBtn, { BackgroundColor3 = Theme.Header }, 0.15)
    VerifyBtn.Text = "..."

    task.spawn(function()
        local ok, res = pcall(function() return Junkie.check_key(key) end)

        local function resetBtn()
            Tween(VerifyBtn, { BackgroundColor3 = Theme.Accent }, 0.15)
            VerifyBtn.Text = "Verify Key"
            verifying = false
        end

        if not ok or not res then
            FinishProgress(false)
            SetStatus("Verification failed", "error")
            resetBtn()
            return
        end

        if res.valid then
            if res.message == "KEYLESS" then
                getgenv().SCRIPT_KEY = "KEYLESS"
                SaveKey("KEYLESS")
                HookTamper()
                if not LoadScript() then resetBtn() end
            elseif res.message == "KEY_VALID" then
                getgenv().SCRIPT_KEY = key
                getgenv().KEYCONNECT  = "WnwtHwXOzBRiJEqbgfCWeprk1EvDf7Te7BnmscOLlVj2DT"
                SaveKey(key)
                HookTamper()
                if not LoadScript() then resetBtn() end
            else
                FinishProgress(false)
                SetStatus("Key invalid or expired", "error")
                resetBtn()
            end
        else
            FinishProgress(false)
            SetStatus("Key invalid or expired", "error")
            resetBtn()
        end
    end)
end

VerifyBtn.MouseButton1Click:Connect(function()
    VerifyKey(KeyBox.Text)
end)

KeyBox.FocusLost:Connect(function(enter)
    if enter then VerifyKey(KeyBox.Text) end
end)

GetBtn.MouseButton1Click:Connect(function()
    local link = Junkie.get_key_link()
    if setclipboard then
        setclipboard(link)
        SetStatus("Link copied to clipboard", "success")
    else
        SetStatus("Open key link in browser", "active")
    end
end)

Tween(WinScale, { Scale = 1 }, 0.45, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
Tween(Blur, { Size = 18 }, 0.45)

task.defer(function()
    local saved = GetSavedKey()
    if saved then
        KeyBox.Text = saved
        SetStatus("Checking saved key...", "active")
        task.wait(0.5)
        VerifyKey(saved)
    end
end)

while not getgenv().SCRIPT_KEY do task.wait(0.1) end

